#!/bin/sh
# R21 Windows cross-build host-side moduleinfotool bridge.
# The SDK's post-build step invokes $<TARGET_FILE:moduleinfotool> (a PE
# .exe) on the Linux build host -- impossible to execute (wine blocked).
# This wrapper (planted at bin/moduleinfotool.exe after configure) copies
# the moduleinfo.json generated by the IDENTICAL-variant Linux build (the
# factory metadata -- FUIDs, names, parameters, version -- is a
# compile-time property of the same sources with the same defines, so the
# Linux tool's output is exactly the Windows bundle's metadata).
# Usage: moduleinfotool -create -version V -path <bundle> -output <json>
set -e
PATH_ARG=""
OUTPUT_ARG=""
while [ $# -gt 0 ]; do
    case "$1" in
        -path) PATH_ARG="$2"; shift 2 ;;
        -output) OUTPUT_ARG="$2"; shift 2 ;;
        *) shift ;;
    esac
done
[ -z "$PATH_ARG" ] && exit 1
[ -z "$OUTPUT_ARG" ] && exit 1
BUNDLE="$(basename "$PATH_ARG")"
case "$BUNDLE" in
    PitchLab_Lagrange6_Balanced.vst3)  SRC=build_vst3 ;;
    PitchLab_Lagrange6_Hybrid.vst3)    SRC=build_vst3/lagrange6_hybrid ;;
    PitchLab_ObsKernel6_Balanced.vst3) SRC=build_vst3/obskernel6_decimated ;;
    PitchLab_Lagrange6_FullRate.vst3)  SRC=build_vst3/lagrange6_fullrate ;;
    *) echo "moduleinfotool-host: unknown bundle $BUNDLE" >&2; exit 1 ;;
esac
NATIVE=/home/z/my-project/octavox-work/r21/Octavox_RE_evidence/native
SRCJSON="$NATIVE/$SRC/VST3/Release/$BUNDLE/Contents/Resources/moduleinfo.json"
if [ ! -f "$SRCJSON" ]; then
    echo "moduleinfotool-host: missing source moduleinfo $SRCJSON" >&2
    exit 1
fi
mkdir -p "$(dirname "$OUTPUT_ARG")"
cp "$SRCJSON" "$OUTPUT_ARG"
echo "[R21-host] moduleinfo.json copied for $BUNDLE"
